<script setup lang="ts">
import { computed,onMounted,ref } from 'vue';import { useRouter } from 'vue-router';import { useProjectStore } from '../stores/project';import { useProfileStore } from '../stores/profile'
const cards=useProjectStore(),profiles=useProfileStore(),router=useRouter(),section=ref<'cards'|'profiles'|'analytics'|'inbox'>('cards');onMounted(async()=>{await Promise.all([cards.restore(),profiles.restore()])});const totalViews=computed(()=>profiles.analytics.reduce((n,d)=>n+d.views,0)),totalClicks=computed(()=>profiles.analytics.reduce((n,d)=>n+d.clicks,0));async function duplicate(id:string){const copy=await cards.duplicate(id);if(copy)router.push(`/cards/${copy.id}/edit`)}
</script>
<template><div class="workspace-home"><header><a class="wordmark" href="/">✳ <b>Card Studio</b></a><nav><button v-for="s in ['cards','profiles','analytics','inbox']" :class="{active:section===s}" @click="section=s as any">{{s}}<i v-if="s==='inbox'&&profiles.unreadCount">{{profiles.unreadCount}}</i></button></nav><a class="new-card" href="/cards/new">＋ New card</a></header><main>
  <section v-if="section==='cards'"><div class="workspace-title"><div><small>YOUR WORKSPACE</small><h1>Digital cards</h1><p>Design physical cards and connect each one to a reusable digital profile.</p></div><a href="/cards/new">Create a card →</a></div><div v-if="cards.cards.length" class="card-project-grid"><article v-for="card in cards.cards" :key="card.id"><div class="card-project-preview" :style="{background:card.design.frontBackground,color:card.fields.accent}"><span>{{card.fields.company}}</span><b>{{card.fields.name}}</b><small>{{card.fields.title}}</small><i v-if="card.profileId">▦ Profile attached</i><i v-else>○ No profile</i></div><div><h2>{{card.name}}</h2><p>{{card.profileSlug?`/u/${card.profileSlug}`:'QR/NFC destination not connected'}}</p><div><a :href="`/cards/${card.id}/edit`">Edit card</a><button @click="duplicate(card.id)">Duplicate</button><button @click="cards.remove(card.id)">Delete</button></div></div></article></div><div v-else class="workspace-empty"><b>Your first card starts here.</b><p>Choose a template, personalize both sides, then connect a digital profile.</p><a href="/cards/new">Browse card templates</a></div></section>
  <section v-else-if="section==='profiles'"><div class="workspace-title"><div><small>REUSABLE DESTINATIONS</small><h1>Digital profiles</h1><p>One profile can power the QR and NFC destination on multiple cards.</p></div><a href="/profiles/new">Create profile →</a></div><article class="profile-row"><div class="profile-avatar">{{profiles.profile.displayName.slice(0,1)}}</div><div><h2>{{profiles.profile.displayName}}</h2><p>/u/{{profiles.profile.slug}} · {{profiles.profile.published?'Published':'Draft'}}</p></div><span>{{cards.cards.filter(c=>c.profileId===profiles.profile.id).length}} cards</span><a :href="`/profiles/${profiles.profile.id}/edit`">Manage</a></article></section>
  <section v-else-if="section==='analytics'"><div class="workspace-title"><div><small>PROFILE PERFORMANCE</small><h1>Analytics</h1></div></div><div class="summary-grid"><article><span>Total views</span><b>{{totalViews}}</b></article><article><span>Link clicks</span><b>{{totalClicks}}</b></article><article><span>Click rate</span><b>{{totalViews?Math.round(totalClicks/totalViews*100):0}}%</b></article></div><a class="manage-link" :href="`/profiles/${profiles.profile.id}/edit`">Open detailed profile analytics →</a></section>
  <section v-else><div class="workspace-title"><div><small>CONTACTS</small><h1>Inbox</h1><p>{{profiles.unreadCount}} unread messages from your profile.</p></div></div><div class="workspace-empty"><b>{{profiles.submissions.length?'Manage your messages':'No messages yet'}}</b><a :href="`/profiles/${profiles.profile.id}/edit`">Open profile inbox →</a></div></section>
</main></div></template>
